"""Freshness checks verify generated bytes and leave ordinary repository files unchanged."""

import hashlib
import json
import os
import subprocess
import sys
from pathlib import Path

import pytest

from tensor_grep.cli import codemap as cm
from tensor_grep.cli import codemap_artifacts as artifacts
from tensor_grep.cli.codemap_pinned import PinnedDirectory
from tensor_grep.cli.codemap_publication import LOCK_NAME, Publication, publication_lock


def _project(tmp_path: Path, git: bool = False) -> Path:
    repo = tmp_path / "repo"
    repo.mkdir()
    (repo / "source.py").write_text('def value():\n    return "café"\n', encoding="utf-8")
    if git:
        environment = {**os.environ, "GIT_CONFIG_GLOBAL": os.devnull, "GIT_CONFIG_NOSYSTEM": "1"}
        for args in (
            ["init", "-q"],
            ["add", "source.py"],
            ["-c", "user.name=Test", "-c", "user.email=test@example.test", "commit", "-qm", "base"],
        ):
            subprocess.run(
                ["git", *args],
                cwd=repo,
                env=environment,
                capture_output=True,
                check=True,
                timeout=30,
            )
    return repo


def _paths(repo: Path) -> dict[str, Path]:
    return {"out": repo / "map-output", "index": repo / "index.md"}


def _build(repo: Path) -> dict:
    return cm.build_codemap(repo, **_paths(repo))


def _snapshot(repo: Path) -> dict:
    return {
        str(path.relative_to(repo)): (
            hashlib.sha256(path.read_bytes()).hexdigest() if path.is_file() else None,
            path.stat().st_mtime_ns,
        )
        for path in [repo, *repo.rglob("*")]
    }


def _check(repo: Path, fresh: bool, *, cli: bool = False, **kwargs) -> dict:
    before = _snapshot(repo)
    if cli:
        paths = _paths(repo)
        environment = {
            **os.environ,
            "PYTHONPATH": str(Path(cm.__file__).resolve().parents[2]),
            "PYTHONDONTWRITEBYTECODE": "1",
        }
        result = subprocess.run(
            [
                sys.executable,
                "-m",
                "tensor_grep",
                "codemap",
                str(repo),
                "--out",
                str(paths["out"]),
                "--index",
                str(paths["index"]),
                "--check",
                "--json",
            ],
            cwd=repo,
            env=environment,
            capture_output=True,
            text=True,
            encoding="utf-8",
            timeout=60,
        )
        assert result.returncode == (0 if fresh else 1), result.stderr
        payload = json.loads(result.stdout)
    else:
        payload = cm.check_codemap_freshness(repo, **_paths(repo), **kwargs)
    assert _snapshot(repo) == before
    assert payload["fresh"] is fresh, payload
    assert payload["reason"]
    return payload


@pytest.mark.parametrize("git", [False, True])
@pytest.mark.parametrize("artifact", ["index", "page"])
@pytest.mark.parametrize("mutation", ["edit", "delete"])
def test_generated_output_mutation_is_stale_and_rebuild_repairs(
    tmp_path: Path, git: bool, artifact: str, mutation: str
) -> None:
    repo = _project(tmp_path, git)
    original = hashlib.sha256((repo / "source.py").read_bytes()).hexdigest()
    built = _build(repo)
    assert built["revision"]["status"] == ("present" if git else "unavailable")
    _check(repo, True)
    target = _paths(repo)["index"] if artifact == "index" else _paths(repo)["out"] / "_root.md"
    if mutation == "delete":
        target.unlink()
    else:
        target.write_bytes(target.read_bytes() + b"\nchanged output\n")
    _check(repo, False)
    _build(repo)
    _check(repo, True)
    assert hashlib.sha256((repo / "source.py").read_bytes()).hexdigest() == original


@pytest.mark.parametrize(
    "damage", ["missing", "legacy", "oversize", "partial", "nonobject", "json", "deep-json", "utf8"]
)
def test_unverifiable_stamp_is_stale(tmp_path: Path, monkeypatch, damage: str) -> None:
    repo = _project(tmp_path)
    _build(repo)
    _check(repo, True)
    stamp = _paths(repo)["out"] / cm._COVERAGE_FILENAME
    if damage == "missing":
        stamp.unlink()
    elif damage == "oversize":
        monkeypatch.setattr(artifacts, "MAX_STAMP_BYTES", len(stamp.read_bytes()) - 1)
    elif damage in {"legacy", "partial"}:
        coverage = json.loads(stamp.read_bytes())
        if damage == "legacy":
            coverage.pop("artifact_manifest")
        else:
            coverage["partial"] = True
        stamp.write_text(json.dumps(coverage), encoding="utf-8")
    else:
        stamp.write_bytes(
            {
                "nonobject": b"[]",
                "json": b"{",
                "deep-json": b"[" * 2000 + b"0" + b"]" * 2000,
                "utf8": b"\xff\xfeinvalid utf8",
            }[damage]
        )
    _check(repo, False)


@pytest.mark.parametrize("damage", ["page", "utf8"])
def test_python_entrypoint_reports_stale_json_and_recovers(tmp_path: Path, damage: str) -> None:
    repo = _project(tmp_path)
    _build(repo)
    _check(repo, True, cli=True)
    output = _paths(repo)["out"]
    if damage == "page":
        (output / "_root.md").write_bytes(b"edited generated page\n")
    else:
        (output / cm._COVERAGE_FILENAME).write_bytes(b"\xff\xfeinvalid utf8")
    _check(repo, False)
    result = _check(repo, False, cli=True)
    if damage == "utf8":
        assert "UTF-8" in result["reason"]
    _build(repo)
    _check(repo, True, cli=True)


@pytest.mark.parametrize("parent", ["output", "index"])
def test_missing_publication_lock_is_stale_without_recreation(tmp_path: Path, parent: str) -> None:
    repo = _project(tmp_path)
    _build(repo)
    _check(repo, True)
    lock = (_paths(repo)["out"] if parent == "output" else repo) / LOCK_NAME
    lock.unlink()
    _check(repo, False)
    assert not lock.exists()


def test_missing_output_directory_is_not_created(tmp_path: Path) -> None:
    repo = _project(tmp_path)
    _check(repo, False)
    assert not _paths(repo)["out"].exists()
    assert not (repo / LOCK_NAME).exists()


def test_contended_reader_lock_is_stale_then_recovers(tmp_path: Path) -> None:
    repo = _project(tmp_path)
    _build(repo)
    paths = _paths(repo)
    before = _snapshot(repo)
    with publication_lock(paths["out"], paths["index"], create=False):
        result = cm.check_codemap_freshness(repo, **paths)
        assert result["fresh"] is False
        assert "lock is contended or changed" in result["reason"]
    assert _snapshot(repo) == before
    _check(repo, True)


@pytest.mark.parametrize("phase", ["stamp", "oracle", "artifacts"])
def test_publication_must_remain_unchanged_after_read_and_oracle(
    tmp_path: Path, monkeypatch, phase
):
    repo = _project(tmp_path, git=True)
    built = _build(repo)
    _check(repo, True)
    changed = False
    original_read, original_unchanged = PinnedDirectory.read, Publication.unchanged

    def read(pin, name, cap):
        nonlocal changed
        data = original_read(pin, name, cap)
        if (phase == "stamp" and name == cm._COVERAGE_FILENAME) or (
            phase == "artifacts" and name.endswith(".md")
        ):
            changed = True
        return data

    def revision(root):
        nonlocal changed
        assert root == repo
        changed = True
        return dict(built["revision"])

    monkeypatch.setattr(PinnedDirectory, "read", read)
    monkeypatch.setattr(
        Publication, "unchanged", lambda state: original_unchanged(state) and not changed
    )
    options = {"_revision_identity": revision} if phase == "oracle" else {}
    _check(repo, False, **options)
    assert changed


@pytest.mark.parametrize("git", [False, True])
def test_both_source_oracles_require_successful_artifact_verification(
    tmp_path: Path, monkeypatch, git
):
    repo = _project(tmp_path, git)
    _build(repo)
    _check(repo, True)
    monkeypatch.setattr(artifacts, "verify", lambda *args, **kwargs: False)
    _check(repo, False)
